-- Questões iniciais do Show da Bíblia. Cada registro é publicado com
-- enunciado, explicação e quatro alternativas em pt-BR, en e es.
CREATE TEMP TABLE biblical_question_seed (
  question_id uuid PRIMARY KEY,
  difficulty_level smallint NOT NULL,
  category_id uuid NOT NULL,
  pt_statement text NOT NULL,
  en_statement text NOT NULL,
  es_statement text NOT NULL,
  pt_explanation text NOT NULL,
  en_explanation text NOT NULL,
  es_explanation text NOT NULL,
  pt_options text[] NOT NULL,
  en_options text[] NOT NULL,
  es_options text[] NOT NULL,
  correct_position smallint NOT NULL
) ON COMMIT DROP;

INSERT INTO biblical_question_seed VALUES
('019f9750-0001-7000-8000-000000000001', 1, '019f9749-7a00-7000-8000-000000000001', 'Quem construiu a arca antes do dilúvio?', 'Who built the ark before the flood?', '¿Quién construyó el arca antes del diluvio?', 'Noé construiu a arca conforme a orientação de Deus. Referência: Gênesis 6:14.', 'Noah built the ark according to God''s instructions. Reference: Genesis 6:14.', 'Noé construyó el arca conforme a las instrucciones de Dios. Referencia: Génesis 6:14.', ARRAY['Abraão','Moisés','Noé','Davi'], ARRAY['Abraham','Moses','Noah','David'], ARRAY['Abraham','Moisés','Noé','David'], 3),
('019f9750-0001-7000-8000-000000000002', 1, '019f9749-7a00-7000-8000-000000000001', 'Quem foi o primeiro homem, segundo Gênesis?', 'Who was the first man, according to Genesis?', '¿Quién fue el primer hombre, según Génesis?', 'Deus formou Adão do pó da terra. Referência: Gênesis 2:7.', 'God formed Adam from the dust of the ground. Reference: Genesis 2:7.', 'Dios formó a Adán del polvo de la tierra. Referencia: Génesis 2:7.', ARRAY['Adão','Abel','Noé','Isaque'], ARRAY['Adam','Abel','Noah','Isaac'], ARRAY['Adán','Abel','Noé','Isaac'], 1),
('019f9750-0001-7000-8000-000000000003', 1, '019f9749-7a00-7000-8000-000000000001', 'Quem derrotou o gigante Golias?', 'Who defeated the giant Goliath?', '¿Quién derrotó al gigante Goliat?', 'Davi derrotou Golias com uma funda e uma pedra. Referência: 1 Samuel 17:50.', 'David defeated Goliath with a sling and a stone. Reference: 1 Samuel 17:50.', 'David derrotó a Goliat con una honda y una piedra. Referencia: 1 Samuel 17:50.', ARRAY['Saul','Jônatas','Davi','Sansão'], ARRAY['Saul','Jonathan','David','Samson'], ARRAY['Saúl','Jonatán','David','Sansón'], 3),
('019f9750-0001-7000-8000-000000000004', 1, '019f9749-7a00-7000-8000-000000000001', 'Qual profeta foi engolido por um grande peixe?', 'Which prophet was swallowed by a great fish?', '¿Qué profeta fue tragado por un gran pez?', 'Jonas foi engolido por um grande peixe durante três dias e três noites. Referência: Jonas 1:17.', 'Jonah was swallowed by a great fish for three days and three nights. Reference: Jonah 1:17.', 'Jonás fue tragado por un gran pez durante tres días y tres noches. Referencia: Jonás 1:17.', ARRAY['Elias','Jonas','Isaías','Jeremias'], ARRAY['Elijah','Jonah','Isaiah','Jeremiah'], ARRAY['Elías','Jonás','Isaías','Jeremías'], 2),
('019f9750-0001-7000-8000-000000000005', 1, '019f9749-7a00-7000-8000-000000000001', 'Quem recebeu de Deus os Dez Mandamentos?', 'Who received the Ten Commandments from God?', '¿Quién recibió de Dios los Diez Mandamientos?', 'Deus entregou os Dez Mandamentos a Moisés. Referência: Êxodo 20.', 'God gave the Ten Commandments to Moses. Reference: Exodus 20.', 'Dios entregó los Diez Mandamientos a Moisés. Referencia: Éxodo 20.', ARRAY['Moisés','Arão','Josué','Abraão'], ARRAY['Moses','Aaron','Joshua','Abraham'], ARRAY['Moisés','Aarón','Josué','Abraham'], 1),
('019f9750-0001-7000-8000-000000000006', 1, '019f9749-7a00-7000-8000-000000000002', 'Qual é o nome da mãe de Jesus?', 'What is the name of Jesus'' mother?', '¿Cuál es el nombre de la madre de Jesús?', 'Maria foi escolhida para ser a mãe de Jesus. Referência: Lucas 1:27.', 'Mary was chosen to be the mother of Jesus. Reference: Luke 1:27.', 'María fue escogida para ser la madre de Jesús. Referencia: Lucas 1:27.', ARRAY['Marta','Isabel','Ana','Maria'], ARRAY['Martha','Elizabeth','Anna','Mary'], ARRAY['Marta','Isabel','Ana','María'], 4),
('019f9750-0001-7000-8000-000000000007', 1, '019f9749-7a00-7000-8000-000000000002', 'Quem batizou Jesus?', 'Who baptized Jesus?', '¿Quién bautizó a Jesús?', 'João Batista batizou Jesus no rio Jordão. Referência: Mateus 3:13–17.', 'John the Baptist baptized Jesus in the Jordan River. Reference: Matthew 3:13–17.', 'Juan el Bautista bautizó a Jesús en el río Jordán. Referencia: Mateo 3:13–17.', ARRAY['Pedro','João Batista','André','Tiago'], ARRAY['Peter','John the Baptist','Andrew','James'], ARRAY['Pedro','Juan el Bautista','Andrés','Santiago'], 2),
('019f9750-0001-7000-8000-000000000008', 1, '019f9749-7a00-7000-8000-000000000002', 'Quem ressuscitou Lázaro?', 'Who raised Lazarus from the dead?', '¿Quién resucitó a Lázaro?', 'Jesus chamou Lázaro para fora do túmulo. Referência: João 11:43–44.', 'Jesus called Lazarus out of the tomb. Reference: John 11:43–44.', 'Jesús llamó a Lázaro para que saliera de la tumba. Referencia: Juan 11:43–44.', ARRAY['Jesus','Pedro','Paulo','João Batista'], ARRAY['Jesus','Peter','Paul','John the Baptist'], ARRAY['Jesús','Pedro','Pablo','Juan el Bautista'], 1),
('019f9750-0001-7000-8000-000000000009', 1, '019f9749-7a00-7000-8000-000000000002', 'Em qual lugar Jesus foi tentado pelo diabo?', 'Where was Jesus tempted by the devil?', '¿En qué lugar fue tentado Jesús por el diablo?', 'Jesus foi levado ao deserto para ser tentado pelo diabo. Referência: Mateus 4:1.', 'Jesus was led into the wilderness to be tempted by the devil. Reference: Matthew 4:1.', 'Jesús fue llevado al desierto para ser tentado por el diablo. Referencia: Mateo 4:1.', ARRAY['No templo','No mar','No deserto','Em Belém'], ARRAY['In the temple','At sea','In the wilderness','In Bethlehem'], ARRAY['En el templo','En el mar','En el desierto','En Belén'], 3),
('019f9750-0001-7000-8000-000000000010', 1, '019f9749-7a00-7000-8000-000000000002', 'Em qual cidade Jesus nasceu?', 'In which city was Jesus born?', '¿En qué ciudad nació Jesús?', 'Jesus nasceu em Belém. Referência: Mateus 2:1.', 'Jesus was born in Bethlehem. Reference: Matthew 2:1.', 'Jesús nació en Belén. Referencia: Mateo 2:1.', ARRAY['Nazaré','Jerusalém','Jericó','Belém'], ARRAY['Nazareth','Jerusalem','Jericho','Bethlehem'], ARRAY['Nazaret','Jerusalén','Jericó','Belén'], 4),
('019f9750-0002-7000-8000-000000000011', 2, '019f9749-7a00-7000-8000-000000000001', 'Qual era o nome do filho prometido por Deus a Abraão e Sara?', 'What was the name of the son God promised to Abraham and Sarah?', '¿Cuál era el nombre del hijo que Dios prometió a Abraham y Sara?', 'Isaque foi o filho prometido a Abraão e Sara. Referência: Gênesis 21:1–3.', 'Isaac was the son promised to Abraham and Sarah. Reference: Genesis 21:1–3.', 'Isaac fue el hijo prometido a Abraham y Sara. Referencia: Génesis 21:1–3.', ARRAY['Jacó','Isaque','Esaú','José'], ARRAY['Jacob','Isaac','Esau','Joseph'], ARRAY['Jacob','Isaac','Esaú','José'], 2),
('019f9750-0002-7000-8000-000000000012', 2, '019f9749-7a00-7000-8000-000000000001', 'De qual povo era Rute?', 'What people was Ruth from?', '¿De qué pueblo era Rut?', 'Rute era uma mulher moabita. Referência: Rute 1:4.', 'Ruth was a Moabite woman. Reference: Ruth 1:4.', 'Rut era una mujer moabita. Referencia: Rut 1:4.', ARRAY['Edomita','Egípcia','Moabita','Cananeia'], ARRAY['Edomite','Egyptian','Moabite','Canaanite'], ARRAY['Edomita','Egipcia','Moabita','Cananea'], 3),
('019f9750-0002-7000-8000-000000000013', 2, '019f9749-7a00-7000-8000-000000000001', 'Qual rainha intercedeu diante do rei para salvar o povo judeu?', 'Which queen interceded before the king to save the Jewish people?', '¿Qué reina intercedió ante el rey para salvar al pueblo judío?', 'Ester intercedeu diante do rei em favor de seu povo. Referência: Ester 4:14–16.', 'Esther interceded before the king on behalf of her people. Reference: Esther 4:14–16.', 'Ester intercedió ante el rey a favor de su pueblo. Referencia: Ester 4:14–16.', ARRAY['Jezabel','Bate-Seba','Vasti','Ester'], ARRAY['Jezebel','Bathsheba','Vashti','Esther'], ARRAY['Jezabel','Betsabé','Vasti','Ester'], 4),
('019f9750-0002-7000-8000-000000000014', 2, '019f9749-7a00-7000-8000-000000000001', 'Qual profeta enfrentou os profetas de Baal no monte Carmelo?', 'Which prophet confronted the prophets of Baal on Mount Carmel?', '¿Qué profeta enfrentó a los profetas de Baal en el monte Carmelo?', 'Elias enfrentou os profetas de Baal no monte Carmelo. Referência: 1 Reis 18.', 'Elijah confronted the prophets of Baal on Mount Carmel. Reference: 1 Kings 18.', 'Elías enfrentó a los profetas de Baal en el monte Carmelo. Referencia: 1 Reyes 18.', ARRAY['Eliseu','Elias','Samuel','Jeremias'], ARRAY['Elisha','Elijah','Samuel','Jeremiah'], ARRAY['Eliseo','Elías','Samuel','Jeremías'], 2),
('019f9750-0002-7000-8000-000000000015', 2, '019f9749-7a00-7000-8000-000000000001', 'Quem interpretou o sonho do rei Nabucodonosor sobre uma grande estátua?', 'Who interpreted King Nebuchadnezzar''s dream about a great statue?', '¿Quién interpretó el sueño del rey Nabucodonosor sobre una gran estatua?', 'Daniel interpretou o sonho do rei Nabucodonosor. Referência: Daniel 2.', 'Daniel interpreted King Nebuchadnezzar''s dream. Reference: Daniel 2.', 'Daniel interpretó el sueño del rey Nabucodonosor. Referencia: Daniel 2.', ARRAY['Daniel','Ezequiel','Esdras','Neemias'], ARRAY['Daniel','Ezekiel','Ezra','Nehemiah'], ARRAY['Daniel','Ezequiel','Esdras','Nehemías'], 1),
('019f9750-0002-7000-8000-000000000016', 2, '019f9749-7a00-7000-8000-000000000002', 'Quem desceu sobre os discípulos no dia de Pentecostes?', 'Who came upon the disciples on the day of Pentecost?', '¿Quién descendió sobre los discípulos el día de Pentecostés?', 'O Espírito Santo veio sobre os discípulos no dia de Pentecostes. Referência: Atos 2:1–4.', 'The Holy Spirit came upon the disciples on the day of Pentecost. Reference: Acts 2:1–4.', 'El Espíritu Santo vino sobre los discípulos el día de Pentecostés. Referencia: Hechos 2:1–4.', ARRAY['Um anjo','Moisés','Elias','O Espírito Santo'], ARRAY['An angel','Moses','Elijah','The Holy Spirit'], ARRAY['Un ángel','Moisés','Elías','El Espíritu Santo'], 4),
('019f9750-0002-7000-8000-000000000017', 2, '019f9749-7a00-7000-8000-000000000001', 'Qual cidade teve suas muralhas derrubadas após o toque das trombetas?', 'Which city had its walls fall after the trumpets sounded?', '¿Qué ciudad tuvo sus murallas derribadas después del toque de las trompetas?', 'As muralhas de Jericó caíram após o toque das trombetas. Referência: Josué 6.', 'The walls of Jericho fell after the trumpets sounded. Reference: Joshua 6.', 'Las murallas de Jericó cayeron después del toque de las trompetas. Referencia: Josué 6.', ARRAY['Nínive','Samaria','Jericó','Hebrom'], ARRAY['Nineveh','Samaria','Jericho','Hebron'], ARRAY['Nínive','Samaria','Jericó','Hebrón'], 3),
('019f9750-0002-7000-8000-000000000018', 2, '019f9749-7a00-7000-8000-000000000002', 'Qual era o nome do pai de João Batista?', 'What was the name of John the Baptist''s father?', '¿Cuál era el nombre del padre de Juan el Bautista?', 'Zacarias era o pai de João Batista. Referência: Lucas 1:5–13.', 'Zechariah was the father of John the Baptist. Reference: Luke 1:5–13.', 'Zacarías era el padre de Juan el Bautista. Referencia: Lucas 1:5–13.', ARRAY['Simeão','Zacarias','José','Eli'], ARRAY['Simeon','Zechariah','Joseph','Eli'], ARRAY['Simeón','Zacarías','José','Elí'], 2),
('019f9750-0002-7000-8000-000000000019', 2, '019f9749-7a00-7000-8000-000000000001', 'Quem cortou o cabelo de Sansão?', 'Who cut Samson''s hair?', '¿Quién cortó el cabello de Sansón?', 'Dalila mandou cortar o cabelo de Sansão. Referência: Juízes 16:17–19.', 'Delilah had Samson''s hair cut. Reference: Judges 16:17–19.', 'Dalila mandó cortar el cabello de Sansón. Referencia: Jueces 16:17–19.', ARRAY['Dalila','Débora','Rute','Mical'], ARRAY['Delilah','Deborah','Ruth','Michal'], ARRAY['Dalila','Débora','Rut','Mical'], 1),
('019f9750-0002-7000-8000-000000000020', 2, '019f9749-7a00-7000-8000-000000000002', 'Qual discípulo de Jesus trabalhava como cobrador de impostos?', 'Which disciple of Jesus worked as a tax collector?', '¿Qué discípulo de Jesús trabajaba como recaudador de impuestos?', 'Mateus trabalhava como cobrador de impostos quando Jesus o chamou. Referência: Mateus 9:9.', 'Matthew worked as a tax collector when Jesus called him. Reference: Matthew 9:9.', 'Mateo trabajaba como recaudador de impuestos cuando Jesús lo llamó. Referencia: Mateo 9:9.', ARRAY['Pedro','Judas Tadeu','Bartolomeu','Mateus'], ARRAY['Peter','Jude Thaddeus','Bartholomew','Matthew'], ARRAY['Pedro','Judas Tadeo','Bartolomé','Mateo'], 4),
('019f9750-0003-7000-8000-000000000021', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual era o nome da esposa do profeta Oséias?', 'What was the name of the prophet Hosea''s wife?', '¿Cuál era el nombre de la esposa del profeta Oseas?', 'Gômer foi a esposa de Oséias. Referência: Oséias 1:2–3.', 'Gomer was Hosea''s wife. Reference: Hosea 1:2–3.', 'Gomer fue la esposa de Oseas. Referencia: Oseas 1:2–3.', ARRAY['Raquel','Miriã','Gômer','Abigail'], ARRAY['Rachel','Miriam','Gomer','Abigail'], ARRAY['Raquel','Miriam','Gomer','Abigail'], 3),
('019f9750-0003-7000-8000-000000000022', 3, '019f9749-7a00-7000-8000-000000000002', 'Quem foi escolhido por sorteio para ocupar o lugar de Judas Iscariotes entre os apóstolos?', 'Who was chosen by lot to take Judas Iscariot''s place among the apostles?', '¿Quién fue elegido por sorteo para ocupar el lugar de Judas Iscariote entre los apóstoles?', 'Matias foi escolhido por sorteio para ocupar o lugar de Judas Iscariotes. Referência: Atos 1:15–26.', 'Matthias was chosen by lot to take Judas Iscariot''s place. Reference: Acts 1:15–26.', 'Matías fue elegido por sorteo para ocupar el lugar de Judas Iscariote. Referencia: Hechos 1:15–26.', ARRAY['Matias','Barnabé','Silas','Timóteo'], ARRAY['Matthias','Barnabas','Silas','Timothy'], ARRAY['Matías','Bernabé','Silas','Timoteo'], 1),
('019f9750-0003-7000-8000-000000000023', 3, '019f9749-7a00-7000-8000-000000000001', 'Quem escondeu cem profetas do Senhor em cavernas durante a perseguição de Jezabel?', 'Who hid one hundred prophets of the Lord in caves during Jezebel''s persecution?', '¿Quién escondió a cien profetas del Señor en cuevas durante la persecución de Jezabel?', 'Obadias escondeu cem profetas do Senhor em cavernas. Referência: 1 Reis 18:3–4.', 'Obadiah hid one hundred prophets of the Lord in caves. Reference: 1 Kings 18:3–4.', 'Abdías escondió a cien profetas del Señor en cuevas. Referencia: 1 Reyes 18:3–4.', ARRAY['Acabe','Elias','Eliseu','Obadias'], ARRAY['Ahab','Elijah','Elisha','Obadiah'], ARRAY['Acab','Elías','Eliseo','Abdías'], 4),
('019f9750-0003-7000-8000-000000000024', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual profeta teve a visão de um rolo que voava?', 'Which prophet had a vision of a flying scroll?', '¿Qué profeta tuvo la visión de un rollo que volaba?', 'Zacarias teve a visão de um rolo que voava. Referência: Zacarias 5:1–2.', 'Zechariah had a vision of a flying scroll. Reference: Zechariah 5:1–2.', 'Zacarías tuvo la visión de un rollo que volaba. Referencia: Zacarías 5:1–2.', ARRAY['Malaquias','Zacarias','Joel','Naum'], ARRAY['Malachi','Zechariah','Joel','Nahum'], ARRAY['Malaquías','Zacarías','Joel','Nahúm'], 2),
('019f9750-0003-7000-8000-000000000025', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual homem morreu após tocar na arca da aliança?', 'Which man died after touching the ark of the covenant?', '¿Qué hombre murió después de tocar el arca del pacto?', 'Uzá morreu após tocar na arca da aliança. Referência: 2 Samuel 6:6–7.', 'Uzzah died after touching the ark of the covenant. Reference: 2 Samuel 6:6–7.', 'Uzá murió después de tocar el arca del pacto. Referencia: 2 Samuel 6:6–7.', ARRAY['Abinadabe','Eleazar','Quis','Uzá'], ARRAY['Abinadab','Eleazar','Kish','Uzzah'], ARRAY['Abinadab','Eleazar','Cis','Uzá'], 4),
('019f9750-0003-7000-8000-000000000026', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual sumo sacerdote encontrou o Livro da Lei no templo, no reinado de Josias?', 'Which high priest found the Book of the Law in the temple during Josiah''s reign?', '¿Qué sumo sacerdote encontró el Libro de la Ley en el templo durante el reinado de Josías?', 'Hilquias encontrou o Livro da Lei no templo. Referência: 2 Reis 22:8.', 'Hilkiah found the Book of the Law in the temple. Reference: 2 Kings 22:8.', 'Hilcías encontró el Libro de la Ley en el templo. Referencia: 2 Reyes 22:8.', ARRAY['Abiatar','Zadoque','Hilquias','Joiada'], ARRAY['Abiathar','Zadok','Hilkiah','Jehoiada'], ARRAY['Abiatar','Sadoc','Hilcías','Joiada'], 3),
('019f9750-0003-7000-8000-000000000027', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual rei respondeu ao povo que tornaria seu jugo ainda mais pesado que o de seu pai?', 'Which king told the people that he would make their yoke heavier than his father''s?', '¿Qué rey respondió al pueblo que haría su yugo aún más pesado que el de su padre?', 'Roboão disse que tornaria o jugo do povo mais pesado que o de seu pai. Referência: 1 Reis 12:14.', 'Rehoboam said he would make the people''s yoke heavier than his father''s. Reference: 1 Kings 12:14.', 'Roboam dijo que haría el yugo del pueblo más pesado que el de su padre. Referencia: 1 Reyes 12:14.', ARRAY['Jeroboão','Roboão','Asa','Acabe'], ARRAY['Jeroboam','Rehoboam','Asa','Ahab'], ARRAY['Jeroboam','Roboam','Asa','Acab'], 2),
('019f9750-0003-7000-8000-000000000028', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual era o nome do pai de Bezalel, artesão escolhido para trabalhar no tabernáculo?', 'What was the name of Bezalel''s father, the craftsman chosen to work on the tabernacle?', '¿Cuál era el nombre del padre de Bezalel, artesano elegido para trabajar en el tabernáculo?', 'Uri era o pai de Bezalel. Referência: Êxodo 31:2.', 'Uri was Bezalel''s father. Reference: Exodus 31:2.', 'Uri era el padre de Bezalel. Referencia: Éxodo 31:2.', ARRAY['Aoliabe','Hur','Eleazar','Uri'], ARRAY['Oholiab','Hur','Eleazar','Uri'], ARRAY['Aholiab','Hur','Eleazar','Uri'], 4),
('019f9750-0003-7000-8000-000000000029', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual mulher matou Sísera com uma estaca?', 'Which woman killed Sisera with a tent peg?', '¿Qué mujer mató a Sísara con una estaca?', 'Jael matou Sísera com uma estaca. Referência: Juízes 4:21.', 'Jael killed Sisera with a tent peg. Reference: Judges 4:21.', 'Jael mató a Sísara con una estaca. Referencia: Jueces 4:21.', ARRAY['Jael','Débora','Noemi','Ana'], ARRAY['Jael','Deborah','Naomi','Anna'], ARRAY['Jael','Débora','Noemí','Ana'], 1),
('019f9750-0003-7000-8000-000000000030', 3, '019f9749-7a00-7000-8000-000000000001', 'Qual profeta teve a visão de um vale cheio de ossos secos?', 'Which prophet had a vision of a valley full of dry bones?', '¿Qué profeta tuvo la visión de un valle lleno de huesos secos?', 'Ezequiel teve a visão de um vale cheio de ossos secos. Referência: Ezequiel 37:1–10.', 'Ezekiel had a vision of a valley full of dry bones. Reference: Ezekiel 37:1–10.', 'Ezequiel tuvo la visión de un valle lleno de huesos secos. Referencia: Ezequiel 37:1–10.', ARRAY['Daniel','Isaías','Ezequiel','Jeremias'], ARRAY['Daniel','Isaiah','Ezekiel','Jeremiah'], ARRAY['Daniel','Isaías','Ezequiel','Jeremías'], 3);

-- O status começa como DRAFT: o trigger de publicação exige as traduções e
-- alternativas, que são inseridas nas próximas etapas desta mesma migration.
INSERT INTO questions (id, difficulty_level, category_id, status, created_by_user_id)
SELECT question_id, difficulty_level, category_id, 'DRAFT', '019f9749-5ada-702d-93ca-15664a51cd6a'
FROM biblical_question_seed
ON CONFLICT (id) DO UPDATE
SET difficulty_level = EXCLUDED.difficulty_level,
    category_id = EXCLUDED.category_id,
    updated_at = now();

INSERT INTO question_translations (question_id, language_code, statement, explanation)
SELECT seed.question_id, translation.language_code, translation.statement, translation.explanation
FROM biblical_question_seed AS seed
CROSS JOIN LATERAL (
  VALUES
    ('pt-BR', seed.pt_statement, seed.pt_explanation),
    ('en', seed.en_statement, seed.en_explanation),
    ('es', seed.es_statement, seed.es_explanation)
) AS translation(language_code, statement, explanation)
ON CONFLICT (question_id, language_code) DO UPDATE
SET statement = EXCLUDED.statement,
    explanation = EXCLUDED.explanation;

INSERT INTO answer_options (question_id, position, is_correct)
SELECT seed.question_id, option.position::smallint, option.position = seed.correct_position
FROM biblical_question_seed AS seed
CROSS JOIN LATERAL unnest(seed.pt_options) WITH ORDINALITY AS option(content, position)
ON CONFLICT (question_id, position) DO UPDATE
SET is_correct = EXCLUDED.is_correct;

INSERT INTO answer_option_translations (answer_option_id, language_code, content)
SELECT answer_option.id, translation.language_code, translation.content
FROM biblical_question_seed AS seed
JOIN answer_options AS answer_option ON answer_option.question_id = seed.question_id
CROSS JOIN LATERAL (
  VALUES
    ('pt-BR', seed.pt_options[answer_option.position]),
    ('en', seed.en_options[answer_option.position]),
    ('es', seed.es_options[answer_option.position])
) AS translation(language_code, content)
ON CONFLICT (answer_option_id, language_code) DO UPDATE
SET content = EXCLUDED.content;

UPDATE questions AS question
SET status = 'PUBLISHED',
    published_at = COALESCE(question.published_at, now()),
    updated_at = now()
FROM biblical_question_seed AS seed
WHERE question.id = seed.question_id;
